patch:
diff --git a/src/transport/channel/channel.c b/src/transport/channel/channel.c
index 8474686..684bf0f 100644
--- a/src/transport/channel/channel.c
+++ b/src/transport/channel/channel.c
@@ -2422,8 +2422,23 @@ static void tr_channel_open_progress_on_owner(struct tr_channel *channel)
 	}
 }

+static _Atomic uint64_t reset_probe_calls, reset_probe_visits, reset_probe_matches, reset_probe_cpu_ns;
+
+void tr_reset_scan_probe_read(uint64_t out[4])
+{
+    out[0] = atomic_load(&reset_probe_calls);
+    out[1] = atomic_load(&reset_probe_visits);
+    out[2] = atomic_load(&reset_probe_matches);
+    out[3] = atomic_load(&reset_probe_cpu_ns);
+}
+
 static void tr_channel_reset_progress_on_owner(struct tr_channel *channel)
 {
+    struct timespec probe_begin = {0}, probe_end = {0};
+    uint64_t probe_matches = 0;
+    int probe = channel->config.max_streams == 40000U;
+    if (probe)
+        (void)clock_gettime(CLOCK_THREAD_CPUTIME_ID, &probe_begin);
 	uint32_t start;

 	pthread_mutex_lock(&channel->lock);
@@ -2454,6 +2469,7 @@ static void tr_channel_reset_progress_on_owner(struct tr_channel *channel)
 			pthread_mutex_unlock(&channel->lock);
 			continue;
 		}
+        ++probe_matches;
 		if (stream->connection_retired) {
 			int job_pending =
 			        (stream->rx_transform_job &&
@@ -2554,6 +2570,15 @@ static void tr_channel_reset_progress_on_owner(struct tr_channel *channel)
 	pthread_mutex_lock(&channel->lock);
 	channel->reset_progressing = 0;
 	pthread_mutex_unlock(&channel->lock);
+    if (probe) {
+        (void)clock_gettime(CLOCK_THREAD_CPUTIME_ID, &probe_end);
+        uint64_t begin_ns = (uint64_t)probe_begin.tv_sec * 1000000000U + probe_begin.tv_nsec;
+        uint64_t end_ns = (uint64_t)probe_end.tv_sec * 1000000000U + probe_end.tv_nsec;
+        atomic_fetch_add(&reset_probe_calls, 1U);
+        atomic_fetch_add(&reset_probe_visits, channel->config.max_streams);
+        atomic_fetch_add(&reset_probe_matches, probe_matches);
+        atomic_fetch_add(&reset_probe_cpu_ns, end_ns - begin_ns);
+    }
 }

 static int tr_channel_handle_stream_reset(struct tr_channel *channel,
diff --git a/tests/test_stream_reset.c b/tests/test_stream_reset.c
index f1c07b9..92fe60e 100644
