+++ b/tests/test_stream_reset.c
@@ -3250,6 +3250,8 @@ static void test_wire_shape(uint16_t type)
 	}
 }

+void tr_reset_scan_probe_read(uint64_t out[4]);
+
 int main(void)
 {
 	test_reset_rejects_compressed_data_lane_flag();
@@ -3333,6 +3335,11 @@ int main(void)
 	for (enum invalid_kind k = UNKNOWN_RESET; k <= EVICTED_RESET; ++k)
 		test_invalid(k);
 	test_split_frontier();
+    uint64_t probe[4];
+    tr_reset_scan_probe_read(probe);
+    printf("reset-scan-probe: calls=%llu visits=%llu matches=%llu cpu_ns=%llu\n",
+           (unsigned long long)probe[0], (unsigned long long)probe[1],
+           (unsigned long long)probe[2], (unsigned long long)probe[3]);
 	puts("stream_reset: wire, long FIFO turnover, feature, pressure, retry, retirement, "
 	     "ID exhaustion passed");
 	return 0;
